import{_ as e,c as i,o as r,a2 as t}from"./chunks/framework.CIiVzG-O.js";const s=JSON.parse('{"title":"隱私政策","description":"qDiff 不收集你的資料。了解 App 在 Mac 上讀取什麼，以及購買如何處理。","frontmatter":{"title":"隱私政策","description":"qDiff 不收集你的資料。了解 App 在 Mac 上讀取什麼，以及購買如何處理。"},"headers":[],"relativePath":"zh-TW/privacy/index.md","filePath":"zh-TW/privacy/index.md","lastUpdated":1793948370000}'),o={name:"zh-TW/privacy/index.md"};function l(p,a,n,h,d,c){return r(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="隱私政策" tabindex="-1">隱私政策 <a class="header-anchor" href="#隱私政策" aria-label="Permalink to &quot;隱私政策&quot;">​</a></h1><p><em>更新日期：2026 年 11 月 6 日</em></p><p><strong>簡單說：qDiff 不收集任何個人資訊。</strong> 它是一個本地工具，你的檔案始終留在 你的 Mac 上。</p><h2 id="qdiff-會讀取什麼" tabindex="-1">qDiff 會讀取什麼 <a class="header-anchor" href="#qdiff-會讀取什麼" aria-label="Permalink to &quot;qDiff 會讀取什麼&quot;">​</a></h2><p>qDiff 只打開你在 App 裡主動選擇的檔案與資料夾，並在本機完成比較、把結果顯示 給你。如果你授權過某個資料夾，這份授權只是為了方便下次使用，隨時可以在設定裡 取消。我們不會上傳任何內容。</p><h2 id="我們不做的事" tabindex="-1">我們不做的事 <a class="header-anchor" href="#我們不做的事" aria-label="Permalink to &quot;我們不做的事&quot;">​</a></h2><ul><li>不收集姓名、信箱、使用統計。</li><li>不跨 App 或跨網站追蹤你。</li><li>不要求註冊帳號或登入。</li><li>不展示廣告，也不含資料統計或第三方追蹤。</li><li>不把你的檔案同步或備份到任何伺服器。</li></ul><h2 id="關於連網" tabindex="-1">關於連網 <a class="header-anchor" href="#關於連網" aria-label="Permalink to &quot;關於連網&quot;">​</a></h2><p>qDiff 離線可用。唯一可選的網路請求來自 App 內「更多應用程式」頁面，它只會讀取 一份公開的應用程式清單；這個請求不包含任何關於你、你的檔案或裝置的資訊，也不會 回傳使用資料。</p><h2 id="關於購買" tabindex="-1">關於購買 <a class="header-anchor" href="#關於購買" aria-label="Permalink to &quot;關於購買&quot;">​</a></h2><p>可選的一次性購買完全由 Mac App Store 與你的 Apple ID 處理，我們看不到你的 付款資訊。你可以在 App 內的設定裡隨時恢復購買。</p><h2 id="關於本網站" tabindex="-1">關於本網站 <a class="header-anchor" href="#關於本網站" aria-label="Permalink to &quot;關於本網站&quot;">​</a></h2><p>本站是靜態頁面，沒有登入、沒有造訪統計、沒有廣告 Cookie。打開頁面不需要向我們 提供任何資訊。</p><h2 id="兒童" tabindex="-1">兒童 <a class="header-anchor" href="#兒童" aria-label="Permalink to &quot;兒童&quot;">​</a></h2><p>qDiff 不面向兒童，也不會有意收集任何人的資訊。</p><h2 id="變更" tabindex="-1">變更 <a class="header-anchor" href="#變更" aria-label="Permalink to &quot;變更&quot;">​</a></h2><p>如果政策有調整，我們會更新本頁和上面的日期；涉及 App 讀取內容的變更，也會在 App 內說明。</p><h2 id="聯絡" tabindex="-1">聯絡 <a class="header-anchor" href="#聯絡" aria-label="Permalink to &quot;聯絡&quot;">​</a></h2><p>對隱私有疑問，寫信到 <a href="mailto:qdiff@w3cub.com" target="_blank" rel="noreferrer">qdiff@w3cub.com</a>。</p>',19)])])}const q=e(o,[["render",l]]);export{s as __pageData,q as default};
